using Microsoft.EntityFrameworkCore;

// Cosmos DB project context — demonstrates EF Core 9 breaking change fixes
class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "MyDatabase");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Session>(b =>
        {
            b.ToContainer("Sessions");

            // Fix 1: EF Core 9 renamed the default discriminator from "Discriminator" to "$type".
            // Existing documents use "Discriminator", so explicitly preserve the old name.
            b.HasDiscriminator<string>("Discriminator");

            // Fix 2: EF Core 9 no longer embeds the discriminator in the JSON `id` property.
            // Existing documents have the old compound format (e.g., "Session|abc123").
            // Preserve old format so existing documents remain accessible.
            b.HasRootDiscriminatorInJsonId(true);
        });
    }

    // Fix 3: EF Core 9 Cosmos provider no longer supports synchronous I/O.
    // All sync calls (ToList, SaveChanges, First, etc.) now throw.
    // Use async equivalents instead.
    public async Task<List<Session>> GetActiveSessionsAsync()
    {
        // BEFORE (breaks in EF Core 9):
        //   return Sessions.Where(s => s.IsActive).ToList();
        return await Sessions.Where(s => s.IsActive).ToListAsync();
    }

    public async Task AddSessionAsync(Session session)
    {
        Sessions.Add(session);
        // BEFORE (breaks in EF Core 9):
        //   SaveChanges();
        await SaveChangesAsync();
    }
}

class Session
{
    public string Id { get; set; } = string.Empty;
    public string UserId { get; set; } = string.Empty;
    public bool IsActive { get; set; }
}

